'use strict';function getVehicleIdFromURL(){const params=new URLSearchParams(window.location.search);return params.get('vehicle_id');}async function fetchVehicleData(id){try{const response=await fetch('data/vehicles.json');if(!response.ok){throw new Error('Failed to load vehicle data');}const vehicles=await response.json();return vehicles.find((v)=>v.id===id)||null;}catch(err){console.error('Error fetching vehicle data:',err);return null;}}function prePopulateForm(vehicle){const vehicleInterestInput=document.getElementById('vehicle-interest');const subjectSelect=document.getElementById('subject');if(vehicleInterestInput&&vehicle){const label=[vehicle.year,vehicle.make,vehicle.model].filter(Boolean).join(' ');vehicleInterestInput.value=label;}if(subjectSelect){const vehicleOption=Array.from(subjectSelect.options).find((opt)=>opt.value==='Vehicle Inquiry');if(vehicleOption){subjectSelect.value='Vehicle Inquiry';}}}function validateField(fieldId){const field=document.getElementById(fieldId);if(!field)return true;const value=field.value.trim();let errorMessage='';switch(fieldId){case 'name':if(!value){errorMessage='Full name is required.';}break;case 'email':{const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if(!value){errorMessage='Email address is required.';}else if(!emailRegex.test(value)){errorMessage='Please enter a valid email address.';}break;}case 'phone':if(value&&!/^[\(\)\s\-\d+]{7,20}$/.test(value)){errorMessage='Please enter a valid phone number.';}break;case 'subject':if(!value){errorMessage='Please select a subject.';}break;case 'message':if(!value){errorMessage='Message is required.';}else if(value.length<10){errorMessage='Message must be at least 10 characters.';}break;default:break;}if(errorMessage){showValidationError(fieldId,errorMessage);return false;}clearFieldError(fieldId);return true;}function validateForm(){const fieldsToValidate=['name','email','phone','subject','message'];let isValid=true;let firstInvalidField=null;clearValidationErrors();for(const fieldId of fieldsToValidate){const fieldValid=validateField(fieldId);if(!fieldValid&&!firstInvalidField){firstInvalidField=fieldId;}isValid=isValid&&fieldValid;}if(firstInvalidField){const el=document.getElementById(firstInvalidField);if(el)el.focus();}return isValid;}function showValidationError(fieldId,message){const field=document.getElementById(fieldId);const errorEl=document.getElementById(`${fieldId}-error`);if(field){field.setAttribute('aria-invalid','true');field.classList.add('invalid');}if(errorEl){errorEl.textContent=message;}}function clearFieldError(fieldId){const field=document.getElementById(fieldId);const errorEl=document.getElementById(`${fieldId}-error`);if(field){field.setAttribute('aria-invalid','false');field.classList.remove('invalid');}if(errorEl){errorEl.textContent='';}}function clearValidationErrors(){const fields=['name','email','phone','subject','message'];fields.forEach((fieldId)=>clearFieldError(fieldId));}function setLoadingState(loading){const submitBtn=document.getElementById('submit-btn');const btnText=submitBtn?submitBtn.querySelector('.btn-text'):null;const btnSpinner=submitBtn?submitBtn.querySelector('.btn-spinner'):null;const form=document.getElementById('contact-form');if(!submitBtn)return;if(loading){submitBtn.disabled=true;submitBtn.setAttribute('aria-busy','true');if(btnText)btnText.textContent='Sending\u2026';if(btnSpinner)btnSpinner.hidden=false;if(form){Array.from(form.elements).forEach((el)=>{if(el!==submitBtn)el.disabled=true;});}}else{submitBtn.disabled=false;submitBtn.setAttribute('aria-busy','false');if(btnText)btnText.textContent='Send Message';if(btnSpinner)btnSpinner.hidden=true;if(form){Array.from(form.elements).forEach((el)=>{el.disabled=false;});}}}async function handleFormSubmit(event){event.preventDefault();const form=event.target;const honeypot=form.querySelector('input[name="_gotcha"]');if(honeypot&&honeypot.value){return;}if(!validateForm()){return;}hideStatusMessages();setLoadingState(true);try{const formData=new FormData(form);const response=await fetch(form.action,{method:'POST',body:formData,headers:{Accept:'application/json'},});if(response.ok){showSuccess();}else{const data=await response.json().catch(()=>({}));console.error('FormSpree error:',data);showError();}}catch(err){console.error('Submission network error:',err);showError();}finally{setLoadingState(false);}}function showSuccess(){const successEl=document.getElementById('form-success');const form=document.getElementById('contact-form');if(successEl){successEl.hidden=false;successEl.scrollIntoView({behavior:'smooth',block:'nearest'});}if(form){form.hidden=true;}setTimeout(()=>{if(successEl)successEl.hidden=true;if(form){form.hidden=false;resetForm();}},5000);}function showError(){const errorEl=document.getElementById('form-error');if(errorEl){errorEl.hidden=false;errorEl.scrollIntoView({behavior:'smooth',block:'nearest'});}}function hideStatusMessages(){const successEl=document.getElementById('form-success');const errorEl=document.getElementById('form-error');if(successEl)successEl.hidden=true;if(errorEl)errorEl.hidden=true;}function resetForm(){const form=document.getElementById('contact-form');if(form){form.reset();}clearValidationErrors();}function formatPhoneNumber(input){const digits=input.value.replace(/\D/g,'').slice(0,10);let formatted='';if(digits.length>0){formatted='('+digits.slice(0,3);}if(digits.length>=4){formatted+=')'+digits.slice(3,6);}if(digits.length>=7){formatted+='-'+digits.slice(6,10);}input.value=formatted;}document.addEventListener('DOMContentLoaded',async()=>{const vehicleId=getVehicleIdFromURL();if(vehicleId){const vehicle=await fetchVehicleData(vehicleId);if(vehicle){prePopulateForm(vehicle);}}const form=document.getElementById('contact-form');if(form){form.addEventListener('submit',handleFormSubmit);}const phoneInput=document.getElementById('phone');if(phoneInput){phoneInput.addEventListener('input',()=>formatPhoneNumber(phoneInput));}const fieldsToValidate=['name','email','phone','subject','message'];fieldsToValidate.forEach((id)=>{const el=document.getElementById(id);if(el){el.addEventListener('blur',()=>validateField(id));}});});